// Domain kernel for "Order" (generated by gherkin-ai).
export type OrderEventType = 'OrderPlaced' | 'OrderCancelled';
export interface OrderCommand { id: string; payload?: Record<string, unknown>; }
export class DomainValidationError extends Error {}

export class OrderAggregate {
  private _version = 0;
  constructor(public readonly id: string) {}

  placeOrder(command: OrderCommand) {
    this.assertValid(command);
    return this.record('OrderPlaced', command.payload ?? {});
  }

  cancelOrder(command: OrderCommand) {
    this.assertValid(command);
    return this.record('OrderCancelled', command.payload ?? {});
  }

  private assertValid(command: OrderCommand): void {
    if (!command || !command.id || !command.id.trim()) throw new DomainValidationError('Command id is required');
    if (command.id !== this.id) throw new DomainValidationError(`Command targets ${command.id}, not ${this.id}`);
  }

  private record(type: OrderEventType, payload: Record<string, unknown>) {
    this._version += 1;
    return { type, aggregateId: this.id, version: this._version, payload };
  }
}
